import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong(), m = (int) nextLong();
        long[] a = new long[n], diff = new long[n + 1];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        for (int i = 0; i < m; i++) {
            diff[(int) nextLong()]++;
            diff[(int) nextLong() + 1]--;
        }
        // Pack (value + 1e9, occurrences in the concatenation <= 1e5 < 2^17) into one sortable long.
        long[] items = new long[n];
        long active = 0;
        for (int i = 0; i < n; i++) {
            active += diff[i];
            items[i] = ((a[i] + 1000000000L) << 17) | active;
        }
        Arrays.sort(items);
        long mask = (1L << 17) - 1, prefix = 0, answer = 0;
        for (int i = 0; i < n;) {
            int j = i;
            long weight = 0, unused = 0;
            while (j < n && (items[j] >>> 17) == (items[i] >>> 17)) {
                long count = items[j] & mask;
                weight += count;
                if (count == 0) unused++;
                j++;
            }
            // Query the strictly smaller weight before adding this value group.
            answer += unused * prefix;
            prefix += weight;
            i = j;
        }
        System.out.println(answer);
    }
}

