import (
	"bufio"
	"fmt"
	"io"
	"os"
	"slices"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n, m := int(nextInt()), int(nextInt())
	a, diff := make([]int64, n), make([]int64, n+1)
	for i := range a {
		a[i] = nextInt()
	}
	for i := 0; i < m; i++ {
		diff[nextInt()]++
		diff[nextInt()+1]--
	}
	// Pack (value + 1e9, occurrences in the concatenation <= 1e5 < 2^17) into one sortable int64.
	items := make([]int64, n)
	active := int64(0)
	for i := 0; i < n; i++ {
		active += diff[i]
		items[i] = (a[i]+1000000000)<<17 | active
	}
	slices.Sort(items)
	const mask = int64(1)<<17 - 1
	prefix, answer := int64(0), int64(0)
	for i := 0; i < n; {
		j := i
		weight, unused := int64(0), int64(0)
		for j < n && items[j]>>17 == items[i]>>17 {
			count := items[j] & mask
			weight += count
			if count == 0 {
				unused++
			}
			j++
		}
		// Query the strictly smaller weight before adding this value group.
		answer += unused * prefix
		prefix += weight
		i = j
	}
	fmt.Println(answer)
}
